INSERT INTO questions (category, question, choices, answer, explanation)
VALUES (
  'General',
  'Ignoring minimum fuel reserve requirements is generally the result of overconfidence, disregarding applicable regulations, or',
  '["physical stress.","lack of flight planning.","impulsivity."]'::jsonb,
  1,
